/*
 * A229999  For every positive integer m, let u(m) = (d(1),d(2),...,d(k)) be
 *          the unitary divisors of m. The sequence (a(n)) consists of
 *          integers of the form d(k)/d(1) + d(k-1)/d(2) + ... + d(k)/d(1).
 * https://oeis.org/A229999
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = integer sums of d(k)/d(1)+d(k-1)/d(2)+...+d(1)/d(k) where
 *            (d(1),…,d(k)) is the list of unitary divisors of m. The sequence
 *            is generated by scanning m = 1,2,3,… and collecting those values
 *            for which the sum is an integer
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 19, u64 n <= 37, u128 n <= 37,
 *            big any n
 * Helpers:   big_pow, factor_u64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/factor_u64.h"   /* factor_u64() */
#include "../utils/big_pow.h"      /* big_pow() */

static seq_t *cache = NULL;      /* cache of computed a(n) values   */
static size_t cache_size = 0;    /* number of terms stored          */
static size_t cache_cap = 0;     /* allocated capacity              */

/* ensure cache has space for at least new_cap elements */
static void ensure_cache_cap(size_t new_cap) {
    if (new_cap <= cache_cap) return;
    size_t cap = new_cap > 8 ? new_cap : 8;
    seq_t *tmp = (seq_t *)realloc(cache, cap * sizeof(seq_t));
    if (!tmp) abort();               /* memory failure */
    cache = tmp;
    cache_cap = cap;
}

seq_t a(idx_t n) {
    if (n == 0) return 0;                 /* offset starts at 1 */

    /* static state keeps the search position between calls   */
    static idx_t next_m = 1;       /* next integer to test      */
    static idx_t produced = 0;     /* how many qualifying terms found */

    /* generate terms until we have at least n terms */
    while (produced < n) {
        idx_t m = next_m++;
        seq_t sum;

        /* factorize m */
        uint64_t primes[64];
        uint64_t exps[64];
        size_t pf_cnt;
        factor_u64((uint64_t)m, primes, exps, &pf_cnt);

        /* For m = 1, no prime factors; the sum is 1 */
        if (pf_cnt == 0) {
            sum = 1;
        } else {
            /* numerator = product (p^{2e}+1)      */
            /* denominator = product p^e           */
            seq_t numerator = 1;
            seq_t denominator = 1;

            for (size_t i = 0; i < pf_cnt; ++i) {
                seq_t p = (seq_t)primes[i];
                seq_t e  = (seq_t)exps[i];

                /* p^{2e} + 1 */
                seq_t p2e = big_pow(p, (seq_t)(2 * exps[i]));
                seq_t term = p2e + 1;
                numerator *= term;

                /* p^e  */
                seq_t pe = big_pow(p, e);
                denominator *= pe;
            }

            /* check integrality */
            if (numerator % denominator == 0) {
                sum = numerator / denominator;
            } else {
                /* not an integer; skip and continue */
                continue;
            }
        }

        /* store the found term */
        ensure_cache_cap(cache_size + 1);
        cache[cache_size++] = sum;
        produced++;
    }

    return cache[n - 1];
}
